//! `architecture-baseline.toml`: existing violations a rule tolerates for now.
//!
//! Each rule that needs a baseline owns one table. The file is generated by
//! `cargo arch --write-baseline`; a missing table means the rule tolerates
//! nothing, which can only make checks stricter.

use std::{collections::BTreeMap, io, path::Path, path::PathBuf};

use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::context::LoadError;

pub const BASELINE_FILE: &str = "architecture-baseline.toml";

const HEADER: &str = "\
# Existing violations of the rules in ARCHITECTURE.toml, tolerated until fixed.
# Generated by `cargo arch --write-baseline`; see crates/tools/archcheck/README.md.
#
# [file_size] maps each production Rust file over the code-line limit to its cap,
# the code-line count it had when listed. Only remove entries or lower caps.
";

#[derive(Debug, Clone, Default, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Baseline {
    /// Repository-relative path to the file's code-line cap.
    #[serde(default)]
    pub file_size: BTreeMap<String, usize>,
}

#[derive(Debug, Error)]
pub enum WriteBaselineError {
    #[error(transparent)]
    Load(#[from] LoadError),
    #[error("could not serialize the baseline: {0}")]
    Serialize(#[from] toml::ser::Error),
    #[error("refusing to write {path}: it is a symlink or resolves outside the repository root")]
    UnsafeTarget { path: PathBuf },
    #[error("could not write {path}: {source}")]
    Write {
        path: PathBuf,
        #[source]
        source: io::Error,
    },
}

impl Baseline {
    pub fn load(path: &Path) -> Result<Self, LoadError> {
        let text = std::fs::read_to_string(path).map_err(|source| LoadError::Read {
            path: path.to_path_buf(),
            source,
        })?;
        let baseline: Self = toml::from_str(&text).map_err(|source| LoadError::Parse {
            path: path.to_path_buf(),
            source,
        })?;
        if let Some(key) = baseline
            .file_size
            .keys()
            .find(|key| !is_normalized_rust_path(key))
        {
            return Err(LoadError::BaselineKey {
                path: path.to_path_buf(),
                key: key.clone(),
            });
        }
        Ok(baseline)
    }

    pub fn render(&self) -> Result<String, toml::ser::Error> {
        Ok(format!("{HEADER}\n{}", toml::to_string(self)?))
    }

    /// Writes the baseline to `path` inside `root`. The tree may not be
    /// trusted, so a symlink, even one that stays inside the root, or a path
    /// that resolves outside it is refused rather than written through.
    pub fn write(&self, root: &Path, path: &Path) -> Result<(), WriteBaselineError> {
        let write_error = |source| WriteBaselineError::Write {
            path: path.to_path_buf(),
            source,
        };
        let unsafe_target = || WriteBaselineError::UnsafeTarget {
            path: path.to_path_buf(),
        };
        match std::fs::symlink_metadata(path) {
            Ok(metadata) if metadata.file_type().is_symlink() => return Err(unsafe_target()),
            Ok(_) => {
                let real_root = root.canonicalize().map_err(write_error)?;
                if !path
                    .canonicalize()
                    .map_err(write_error)?
                    .starts_with(real_root)
                {
                    return Err(unsafe_target());
                }
            }
            Err(err) if err.kind() == io::ErrorKind::NotFound => {}
            Err(err) => return Err(write_error(err)),
        }
        std::fs::write(path, self.render()?).map_err(write_error)
    }
}

/// A repository-relative `.rs` path as the inventory spells it: `/`-separated,
/// with no leading `./` or `/`, no `.` or `..` segment and no empty segment.
/// Anything else could never match a production file.
fn is_normalized_rust_path(key: &str) -> bool {
    key.ends_with(".rs")
        && key
            .split('/')
            .all(|segment| !matches!(segment, "" | "." | ".."))
}
